import json
from rdkit import Chem
from rdkit.Chem import inchi

with open('backend/reference_drugs_200.json') as f:
    drugs_200 = json.load(f)

existing_names = {d['name'].strip().lower() for d in drugs_200}
existing_db = {d['drugbank_id'].strip().upper() for d in drugs_200}
existing_cas = {d.get('cas_number', '').strip() for d in drugs_200 if d.get('cas_number')}
existing_inchikeys = set()
for d in drugs_200:
    m = Chem.MolFromSmiles(d['smiles'])
    if m:
        existing_inchikeys.add(inchi.MolToInchiKey(m))

print(f"Loaded 200 existing reference drugs. {len(existing_inchikeys)} unique InChIKeys.")

