clean_pool = []
for item in CANDIDATE_POOL:
    nm = item['name'].strip().lower()
    db = item['drugbank_id'].strip().upper()
    cas = item['cas_number'].strip()
    m = Chem.MolFromSmiles(item['smiles'])
    if not m:
        print(f"FAILED SMILES: {item['name']}")
        continue
    ik = inchi.MolToInchiKey(m)
    
    colls = []
    if nm in existing_names: colls.append(f"name({nm})")
    if db in existing_db: colls.append(f"db({db})")
    if cas in existing_cas: colls.append(f"cas({cas})")
    if ik in existing_inchikeys: colls.append(f"inchikey({ik})")
    
    if colls:
        print(f"Collision in {item['name']}: {colls}")
    else:
        clean_pool.append(item)

print(f"\nTotal Clean Candidates Available: {len(clean_pool)}")
